import{_ as d,o,c as r,a2 as e}from"./chunks/framework.CuUVYbLV.js";const f=JSON.parse('{"title":"术语表","description":"rolebox 文档全站术语的唯一定义表：按主题分组，每条给出中英文术语、一句话定义与首次出现页面。","frontmatter":{"title":"术语表","description":"rolebox 文档全站术语的唯一定义表：按主题分组，每条给出中英文术语、一句话定义与首次出现页面。"},"headers":[],"relativePath":"06-Appendix/glossary.md","filePath":"06-Appendix/glossary.md"}'),a={name:"06-Appendix/glossary.md"};function n(s,t,l,c,h,i){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="术语表-glossary" tabindex="-1">术语表（Glossary） <a class="header-anchor" href="#术语表-glossary" aria-label="Permalink to &quot;术语表（Glossary）&quot;">​</a></h1><p>这一页回答「文档里的这个词是什么意思」。<strong>术语表是全站唯一定义表</strong>：正文里每个术语在首次出现处就地解释一次，之后直接使用；本页把它们按主题汇总，方便集中查找与横向对照。</p><blockquote><p>相关：<a href="/rolebox-docs/06-Appendix/source-index.html">源码索引</a>｜<a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a>｜<a href="/rolebox-docs/">文档首页</a></p></blockquote><h2 id="角色与资产" tabindex="-1">角色与资产 <a class="header-anchor" href="#角色与资产" aria-label="Permalink to &quot;角色与资产&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话定义</th><th>首次出现</th></tr></thead><tbody><tr><td><strong>角色（role）</strong></td><td>一个含 <code>role.yaml</code> 的目录，定义一个代理的人格、能力与团队。</td><td><a href="/rolebox-docs/02-Guide/create-a-role.html">创建角色</a></td></tr><tr><td><strong>角色目录（role directory）</strong></td><td>存放 <code>role.yaml</code>、提示词、<code>skills/</code>、<code>functions/</code>、<code>references/</code> 的目录，目录名就是角色 id。</td><td><a href="/rolebox-docs/01-Overview/directory-structure.html">目录结构</a></td></tr><tr><td><strong><code>role.yaml</code></strong></td><td>角色的声明文件：身份字段必需，能力、编排与权限字段可选。</td><td><a href="/rolebox-docs/03-Reference/role-yaml.html">role.yaml 参考</a></td></tr><tr><td><strong>提示词文件（prompt file）</strong></td><td>由 <code>prompt_file</code> 指向的外部 Markdown，每次会话全文进入系统提示。</td><td><a href="/rolebox-docs/02-Guide/tutorial/02-first-role.html">教程 02</a></td></tr><tr><td><strong>技能（skill）</strong></td><td>一个含 <code>SKILL.md</code> 的目录；常驻上下文的只有名字与描述，正文按需加载。</td><td><a href="/rolebox-docs/02-Guide/skills.html">技能系统</a></td></tr><tr><td><strong>引用文档（reference）</strong></td><td><code>references/</code> 下的 Markdown；元数据常驻，正文在真的需要时才读入。</td><td><a href="/rolebox-docs/02-Guide/references.html">引用文档</a></td></tr><tr><td><strong>渐进式披露（progressive disclosure）</strong></td><td>先只告诉模型「有什么、什么时候用」，正文等真正需要时再取。</td><td><a href="/rolebox-docs/02-Guide/tutorial/02-first-role.html">教程 02</a></td></tr><tr><td><strong>函数（function）</strong></td><td>一段按需注入系统提示的行为模块，用行首前缀激活，可带门控、参数与状态转换。</td><td><a href="/rolebox-docs/02-Guide/functions.html">函数系统</a></td></tr><tr><td><strong>激活语法（activation syntax）</strong></td><td>写在消息行首、用竖线包裹函数名的前缀，把函数在本次会话中打开。</td><td><a href="/rolebox-docs/02-Guide/functions.html">函数系统</a></td></tr><tr><td><strong>内置函数（built-in function）</strong></td><td>每个角色都有的三个函数：<code>plan</code>、<code>execute</code>、<code>loop</code>。</td><td><a href="/rolebox-docs/02-Guide/functions.html">函数系统</a></td></tr><tr><td><strong>合并语义（merge semantics）</strong></td><td><code>functions:</code> 只往默认清单里追加，移除必须用 <code>disable_functions</code>。</td><td><a href="/rolebox-docs/03-Reference/role-yaml.html">role.yaml 参考</a></td></tr><tr><td><strong>子代理（subagent）</strong></td><td>由父角色声明、在独立会话中执行任务的代理，id 形如 <code>父角色--子代理</code>；未声明的字段从父角色继承。</td><td><a href="/rolebox-docs/02-Guide/subagents.html">子代理</a></td></tr><tr><td><strong>父角色 / 编排器（parent role / orchestrator）</strong></td><td>声明子代理、并把工作派发出去的那个角色。</td><td><a href="/rolebox-docs/02-Guide/tutorial/04-team.html">教程 04</a></td></tr><tr><td><strong>角色模板（template）</strong></td><td><code>rolebox init</code> 可选的角色骨架，决定生成哪些文件与字段。</td><td><a href="/rolebox-docs/03-Reference/cli.html">CLI 参考</a></td></tr><tr><td><strong>注册中心（registry）</strong></td><td>用 <code>registry.yaml</code> 发布与分发角色的仓库。</td><td><a href="/rolebox-docs/03-Reference/registry.html">注册中心</a></td></tr><tr><td><strong>资产（asset）</strong></td><td>角色目录下可单独检索与校验的内容单元，例如技能与引用文档。</td><td><a href="/rolebox-docs/03-Reference/tool-catalog.html">工具目录</a></td></tr></tbody></table><h2 id="图与编排" tabindex="-1">图与编排 <a class="header-anchor" href="#图与编排" aria-label="Permalink to &quot;图与编排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话定义</th><th>首次出现</th></tr></thead><tbody><tr><td><strong>图（graph）</strong></td><td>由 <code>graph_create</code> 创建、用 <code>graph_id</code> 寻址的编排容器。</td><td><a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a></td></tr><tr><td><strong>节点（node）</strong></td><td>图中一次派发给某个代理的工作，内容是一个「代理 + 提示词」元组。</td><td><a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a></td></tr><tr><td><strong>边（edge）</strong></td><td>节点之间的流转关系 <code>from → to</code>；节点本身不定义顺序，顺序由边决定。</td><td><a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a></td></tr><tr><td><strong>边触发方式（edge trigger）</strong></td><td><code>always</code>（上游一有结果就激活）、<code>on_signal</code>（收到指定信号）、<code>on_condition</code>（条件为真）。</td><td><a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a></td></tr><tr><td><strong>join 评估（join evaluation）</strong></td><td>判断一个节点的上游输入是否齐备、从而能否开始执行的评估。</td><td><a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a></td></tr><tr><td><strong>汇聚策略（join strategy）</strong></td><td>join 的判据：<code>all</code>（默认）、<code>any</code>、<code>quorum</code>（需给定数量，且不得超过该节点的入度）。</td><td><a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a></td></tr><tr><td><strong>工作流模式（workflow pattern）</strong></td><td>对「谁先做、谁后做、谁可并行、谁能打回」的结构化表达，只决定边的形状。</td><td><a href="/rolebox-docs/04-Advanced/workflow-patterns.html">工作流模式</a></td></tr><tr><td><strong>拓扑（topology）</strong></td><td>图的预设结构模式；保留 <code>pipeline</code>、<code>review-loop</code>、<code>star</code> 三个内建名字。</td><td><a href="/rolebox-docs/04-Advanced/workflow-patterns.html">工作流模式</a></td></tr><tr><td><strong><code>parent</code>（编排器节点）</strong></td><td>内建拓扑展开时使用的保留节点名；命令式图没有隐式的 <code>parent</code>。</td><td><a href="/rolebox-docs/04-Advanced/workflow-patterns.html">工作流模式</a></td></tr><tr><td><strong>图声明（graph declaration）</strong></td><td>描述节点、边、循环组与预算的 YAML/JSON 文档，与 <code>role.yaml</code> 的角色级 <code>graph</code> 键不是一回事。</td><td><a href="/rolebox-docs/04-Advanced/graph-declaration.html">图声明参考</a></td></tr><tr><td><strong>循环组（loop group）</strong></td><td>被声明成一个有界循环的一组节点，受最大遍历次数硬上限保护。</td><td><a href="/rolebox-docs/02-Guide/tutorial/06-approval-and-loop.html">教程 06</a></td></tr><tr><td><strong><code>max_traversals</code></strong></td><td>循环组的硬性遍历上限；触顶后回边不再生效，成员节点升级为 <code>escalate</code>。</td><td><a href="/rolebox-docs/02-Guide/tutorial/06-approval-and-loop.html">教程 06</a></td></tr><tr><td><strong>审批门（approval gate / HITL）</strong></td><td>节点在需要人工确认处暂停、等批准后再继续的机制。</td><td><a href="/rolebox-docs/02-Guide/tutorial/06-approval-and-loop.html">教程 06</a></td></tr><tr><td><strong><code>needs_approval</code></strong></td><td>节点声明字段，标记「需要人工批准」；命中后节点停在 <code>blocked</code>。</td><td><a href="/rolebox-docs/02-Guide/tutorial/06-approval-and-loop.html">教程 06</a></td></tr><tr><td><strong>非阻塞运行（non-blocking run）</strong></td><td><code>graph_run</code> 派发完就绪根节点就返回，不等它们跑完；调用方应随即结束当前回合。</td><td><a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">教程 05</a></td></tr><tr><td><strong>图中断提醒（graph reminder）</strong></td><td>引擎在全部节点结束或有人工审批待办时注入会话的系统提醒。</td><td><a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">教程 05</a></td></tr><tr><td><strong>级联取消（cascade cancel）</strong></td><td>取消一个节点时，连带取消它传递下游的节点。</td><td><a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a></td></tr><tr><td><strong>预算（budget）</strong></td><td>一张图允许消耗的上限，耗尽后不再派发新节点。</td><td><a href="/rolebox-docs/04-Advanced/graph-declaration.html">图声明参考</a></td></tr><tr><td><strong>数据透传（data passthrough）</strong></td><td>边把上游结果按字段筛选或裁剪后交给下游的机制。</td><td><a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a></td></tr><tr><td><strong>图工具（graph tools）</strong></td><td>8 个命令式建图与运行工具，覆盖创建、加节点、连边、运行、观测、审批与取消。</td><td><a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a></td></tr><tr><td><strong>终止条件（termination，已移除）</strong></td><td>声明式图里决定循环何时停止的配置；已随声明式工作流整体移除，现存终止语义见迁移对照。</td><td><a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a></td></tr><tr><td><strong>循环终止字段（已移除）</strong></td><td><code>max_iterations</code>、<code>result_matches</code>、<code>converged</code>、<code>stuck</code> 四种声明式终止条件，已全部移除。</td><td><a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a></td></tr><tr><td><strong>协作图（已移除）</strong></td><td><code>role.yaml</code> 里声明拓扑与代理列表的配置块，已随声明式工作流移除。</td><td><a href="/rolebox-docs/02-Guide/collaboration-graph.html">协作图（已移除）</a></td></tr></tbody></table><h2 id="运行时与调度" tabindex="-1">运行时与调度 <a class="header-anchor" href="#运行时与调度" aria-label="Permalink to &quot;运行时与调度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话定义</th><th>首次出现</th></tr></thead><tbody><tr><td><strong>派发（dispatch）</strong></td><td>把一段提示词交给某个代理执行的过程；由调度管理器负责生命周期、并发与结果收集。</td><td><a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">教程 05</a></td></tr><tr><td><strong>任务（task）</strong></td><td>一次派发在调度器里的生命周期载体，用任务 id 追踪状态、进度与结果。</td><td><a href="/rolebox-docs/03-Reference/dispatch-config.html">调度配置</a></td></tr><tr><td><strong>看门狗（watchdog）</strong></td><td>周期性核对后台任务状态、回收僵死任务的定时器。</td><td><a href="/rolebox-docs/03-Reference/dispatch-config.html">调度配置</a></td></tr><tr><td><strong>并发槽位（concurrency slot，已移除）</strong></td><td>旧版按模型限制同时在跑的任务数的子系统；已移除，并发度改由图引擎自管。</td><td><a href="/rolebox-docs/03-Reference/dispatch-config.html">调度配置</a></td></tr><tr><td><strong>背压（backpressure，已移除）</strong></td><td>旧版在槽位满载时让调用方排队或延迟重试的保护机制；已随并发槽位子系统移除。</td><td><a href="/rolebox-docs/03-Reference/dispatch-config.html">调度配置</a></td></tr><tr><td><strong>检查点（checkpoint）</strong></td><td>任务执行期间保存的进度快照，重试时可注入，避免重复已完成的工作。</td><td><a href="/rolebox-docs/03-Reference/cli.html">CLI 参考</a></td></tr><tr><td><strong>状态文件（state file）</strong></td><td><code>.rolebox/state/</code> 下按内容哈希命名的运行时状态；结果超出内联限制时另落一份侧车文件。</td><td><a href="/rolebox-docs/01-Overview/directory-structure.html">目录结构</a></td></tr><tr><td><strong>函数状态机（FSM）</strong></td><td>驱动函数在 inactive / gated / active / complete 等状态间转换的模型。</td><td><a href="/rolebox-docs/02-Guide/writing-functions.html">函数规范</a></td></tr><tr><td><strong>门控（gate）</strong></td><td>函数满足特定条件后才被激活的机制；未满足前保持 gated 状态。</td><td><a href="/rolebox-docs/02-Guide/writing-functions.html">函数规范</a></td></tr><tr><td><strong>状态转换（transitions）</strong></td><td>条件满足时激活或停用其它函数的规则，用于跨函数编排。</td><td><a href="/rolebox-docs/02-Guide/writing-functions.html">函数规范</a></td></tr><tr><td><strong>自动延续（continue_until）</strong></td><td>满足即把函数标记为完成、停止自动延续的条件。</td><td><a href="/rolebox-docs/02-Guide/writing-functions.html">函数规范</a></td></tr><tr><td><strong>观察器（observe）</strong></td><td>挂在消息等生命周期事件上运行、并把结果作为校正回注系统提示的钩子。</td><td><a href="/rolebox-docs/02-Guide/writing-functions.html">函数规范</a></td></tr><tr><td><strong>制品（artifact）</strong></td><td>函数声明产生或消费的命名产物，例如 plan 阶段的计划文本。</td><td><a href="/rolebox-docs/02-Guide/writing-functions.html">函数规范</a></td></tr><tr><td><strong>条件表达式（condition expression）</strong></td><td>门控与延续里使用的判定表达式，例如查询「是否观察到某类信号」的 <code>signal_observed</code>。</td><td><a href="/rolebox-docs/02-Guide/writing-functions.html">函数规范</a></td></tr><tr><td><strong>信号（signal）</strong></td><td>不嵌入文本、独立传递的控制信令；共 8 种，分终止、暂停、移交、信息四类。</td><td><a href="/rolebox-docs/04-Advanced/signal-system.html">信号系统</a></td></tr><tr><td><strong>信号类型（signal type）</strong></td><td><code>answer</code>、<code>need_approval</code>、<code>blocked</code>、<code>need_clarification</code>、<code>handoff</code>、<code>progress</code>、<code>revise_needed</code>、<code>escalate</code>。</td><td><a href="/rolebox-docs/04-Advanced/signal-system.html">信号系统</a></td></tr><tr><td><strong>信号台账（signal ledger）</strong></td><td>按会话或函数记录的信号写入历史；信号在裸子代理会话中依然存活。</td><td><a href="/rolebox-docs/04-Advanced/signal-system.html">信号系统</a></td></tr><tr><td><strong>信号传播（signal propagation）</strong></td><td>节点完成时引擎沿边把信号传给下游，无轮询地解锁满足条件的节点。</td><td><a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a></td></tr><tr><td><strong>节点生命周期（NodeStatus）</strong></td><td>节点从注册到结束的状态序列，正常路径是 pending → ready → running → completed → done。</td><td><a href="/rolebox-docs/04-Advanced/runtime-behavior.html">运行时行为</a></td></tr><tr><td><strong>引擎生命周期（EnginePhase）</strong></td><td>一次图执行的阶段：<code>idle</code>、<code>executing</code>、<code>complete</code>。</td><td><a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a></td></tr><tr><td><strong>引擎运行时（EngineRuntime / EngineState）</strong></td><td>承载一次图执行的对象与它持有的状态，提供初始化、运行、恢复与采纳既有进度等方法。</td><td><a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a></td></tr><tr><td><strong>循环协调器（LoopCoordinator）</strong></td><td>驱动 <code>loop</code> 函数顺序多轮执行、并负责取消与持久化恢复的组件。</td><td><a href="/rolebox-docs/04-Advanced/loop-system.html">循环系统</a></td></tr><tr><td><strong>记忆（memory）</strong></td><td>写在项目 <code>.rolebox/memory.db</code> 里、会话启动时按相关度回注给角色的持久条目。</td><td><a href="/rolebox-docs/02-Guide/tutorial/07-memory.html">教程 07</a></td></tr><tr><td><strong>记忆作用域（memory scope）</strong></td><td><code>workspace</code>（项目共享）与 <code>role</code>（写入者自己的角色）；两者同库，按作用域过滤而不是按权限隔离。</td><td><a href="/rolebox-docs/02-Guide/tutorial/07-memory.html">教程 07</a></td></tr><tr><td><strong>会话（session）</strong></td><td>一次对话的上下文与它的持久化记录；记忆与它不同，跨会话存活。</td><td><a href="/rolebox-docs/04-Advanced/session-tools.html">会话工具</a></td></tr><tr><td><strong>会话工具（session tools）</strong></td><td>六个检索与管理会话的工具：列表、读取、搜索、信息、差异、分叉。</td><td><a href="/rolebox-docs/03-Reference/tools/session-memory-tools.html">会话与记忆工具</a></td></tr><tr><td><strong>恢复策略（recovery strategy）</strong></td><td>错误发生时系统自动执行的补救动作，例如重试、压缩上下文、换模型。</td><td><a href="/rolebox-docs/03-Reference/error-handling.html">错误处理</a></td></tr><tr><td><strong>策略链（strategy chain）</strong></td><td>把多个恢复策略按顺序串起来，错误发生时逐个尝试，直到恢复成功或链耗尽。</td><td><a href="/rolebox-docs/03-Reference/error-handling.html">错误处理</a></td></tr><tr><td><strong>错误检测（error detection）</strong></td><td>先判断错误属于哪一类，再据此选择对应的策略链。</td><td><a href="/rolebox-docs/03-Reference/error-handling.html">错误处理</a></td></tr><tr><td><strong>通知（notification）</strong></td><td>由空闲、出错、审批待办等事件触发的外发消息，可配安静时段与频率限制。</td><td><a href="/rolebox-docs/04-Advanced/notification-system.html">通知系统</a></td></tr><tr><td><strong>通知通道（notification channel）</strong></td><td>通知的投递方式：系统提示、声音、自定义命令、Webhook、文件、日志。</td><td><a href="/rolebox-docs/04-Advanced/notification-system.html">通知系统</a></td></tr><tr><td><strong>Hook</strong></td><td>在特定生命周期事件（消息、工具执行前后等）触发并注入自定义逻辑的机制。</td><td><a href="/rolebox-docs/03-Reference/hooks.html">Hook 机制</a></td></tr><tr><td><strong>HookContext API</strong></td><td>传给每个 Hook 处理器的上下文对象，暴露会话、配置与注入能力。</td><td><a href="/rolebox-docs/03-Reference/hooks.html">Hook 机制</a></td></tr><tr><td><strong>扩展点（extension point）</strong></td><td>rolebox 预留给自定义模块接入的位置；每个扩展作用域对应一类扩展点。</td><td><a href="/rolebox-docs/03-Reference/extensions.html">扩展机制</a></td></tr><tr><td><strong>扩展作用域（ExtensionScope）</strong></td><td>可扩展的 7 个封闭词汇表：条件、图拓扑、恢复策略、恢复模式、通知通道、通知事件、观察事件。</td><td><a href="/rolebox-docs/03-Reference/extensions.html">扩展机制</a></td></tr></tbody></table><h2 id="平台与-harness" tabindex="-1">平台与 Harness <a class="header-anchor" href="#平台与-harness" aria-label="Permalink to &quot;平台与 Harness&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话定义</th><th>首次出现</th></tr></thead><tbody><tr><td><strong>Harness（宿主）</strong></td><td>承载 rolebox 插件的宿主程序，支持 opencode、pi、dsh 三种。</td><td><a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a></td></tr><tr><td><strong>平台端口（platform ports）</strong></td><td>rolebox 依赖的宿主能力接口，例如会话客户端、工具工厂与技能面。</td><td><a href="/rolebox-docs/03-Reference/plugin-interface.html">插件接口</a></td></tr><tr><td><strong>平台适配器（platform adapter）</strong></td><td>把某个宿主的能力翻译成平台端口的实现层。</td><td><a href="/rolebox-docs/03-Reference/plugin-interface.html">插件接口</a></td></tr><tr><td><strong>平台门控（platform gating）</strong></td><td>按宿主与平台能力决定某个工具是否可用。</td><td><a href="/rolebox-docs/03-Reference/tools/platform-tools.html">平台工具</a></td></tr><tr><td><strong>PluginCore</strong></td><td>rolebox 插件的核心容器：服务注册、事件总线与工具注册的汇合点。</td><td><a href="/rolebox-docs/01-Overview/architecture-overview.html">架构概览</a></td></tr><tr><td><strong>组合根（composition root）</strong></td><td>程序启动时把全部依赖组件装配起来的位置。</td><td><a href="/rolebox-docs/01-Overview/architecture-overview.html">架构概览</a></td></tr><tr><td><strong>拓扑排序（topological sort）</strong></td><td>按依赖关系决定初始化顺序：先初始化被依赖的服务，再初始化依赖它的服务。</td><td><a href="/rolebox-docs/01-Overview/architecture-overview.html">架构概览</a></td></tr><tr><td><strong>Role Loader / Role Resolver</strong></td><td>加载器扫描角色目录发现 <code>role.yaml</code>；解析器把角色解析出技能、引用、函数与子代理。</td><td><a href="/rolebox-docs/01-Overview/architecture-overview.html">架构概览</a></td></tr><tr><td><strong>引导链（bootstrap chain）</strong></td><td>从插件入口到返回 hook handler 的固定启动顺序。</td><td><a href="/rolebox-docs/01-Overview/architecture-overview.html">架构概览</a></td></tr><tr><td><strong>事件总线（event bus）</strong></td><td>服务之间广播与订阅事件的通道。</td><td><a href="/rolebox-docs/01-Overview/service-architecture.html">服务架构</a></td></tr><tr><td><strong>处理管道（processing pipeline）</strong></td><td>消息从入站、系统提示构建、工具执行到函数解析与恢复的固定阶段序列。</td><td><a href="/rolebox-docs/01-Overview/processing-pipeline.html">处理管道</a></td></tr><tr><td><strong>图执行引擎（graph engine）</strong></td><td>rolebox 统一的多代理编排引擎：把「谁把工作传给谁」建模成有向图来执行。</td><td><a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a></td></tr><tr><td><strong>LSP 工具（code intelligence）</strong></td><td>通过语言服务器提供的诊断、导航、符号与重构工具集。</td><td><a href="/rolebox-docs/03-Reference/tools/lsp-tools.html">LSP 工具</a></td></tr><tr><td><strong>Hashline 编辑（hashline editing）</strong></td><td>用「行号 + 内容哈希」锚点定位文本的编辑方式；行内容一变，锚点即失配。</td><td><a href="/rolebox-docs/04-Advanced/hashline-editing.html">Hashline 编辑</a></td></tr><tr><td><strong>锚点（anchor）</strong></td><td>Hashline 编辑里的定位标记，由行号与内容哈希组成。</td><td><a href="/rolebox-docs/04-Advanced/hashline-editing.html">Hashline 编辑</a></td></tr><tr><td><strong>内容哈希（content hash）</strong></td><td>由行内容算出的短哈希；行内容变化后旧锚点会被拒绝，而不是静默改错行。</td><td><a href="/rolebox-docs/04-Advanced/hashline-editing.html">Hashline 编辑</a></td></tr><tr><td><strong>工具（tool）</strong></td><td>暴露给模型调用的具名能力；与函数的分工见工具目录。</td><td><a href="/rolebox-docs/03-Reference/tool-catalog.html">工具目录</a></td></tr><tr><td><strong>模型别名（model alias）</strong></td><td>把别名映射到真实模型 ID 的配置；解析优先级与热重载规则见参考页。</td><td><a href="/rolebox-docs/03-Reference/model-aliases.html">模型别名</a></td></tr></tbody></table><h2 id="文档与流程" tabindex="-1">文档与流程 <a class="header-anchor" href="#文档与流程" aria-label="Permalink to &quot;文档与流程&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话定义</th><th>首次出现</th></tr></thead><tbody><tr><td><strong>文档分层（Tutorial / Guide / Reference / Internals / Appendix）</strong></td><td>按读者任务划分的五层：教程带你跑通、指南给配方、参考查语义、内部实现讲为什么、附录放术语与出处。</td><td><a href="/rolebox-docs/02-Guide/getting-started.html">教程总览</a></td></tr><tr><td><strong>迁移对照（migration）</strong></td><td>旧写法到新写法的逐条映射；迁移是配置改写，不是执行一条命令。</td><td><a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a></td></tr><tr><td><strong>历史设计记录（design decision archive）</strong></td><td>记录当时设计取舍的存档页，保留原文规模，不是当前 API 参考。</td><td><a href="/rolebox-docs/04-Advanced/design-decisions/memory-strategy.html">记忆策略（历史）</a></td></tr><tr><td><strong>提交消息规范（Conventional Commits）</strong></td><td>贡献流程里约定的提交消息格式，变更日志据此归类。</td><td><a href="/rolebox-docs/05-Contributing/contributing.html">贡献指南</a></td></tr><tr><td><strong>变更日志（CHANGELOG）</strong></td><td>按版本记录变更的文件；发布流程据此生成 Release 说明。</td><td><a href="/rolebox-docs/05-Contributing/contributing.html">贡献指南</a></td></tr></tbody></table><hr><p>术语在正文里首次出现时就地解释；本页只是它们的总目录。找某个行为由哪个模块负责，看<a href="/rolebox-docs/06-Appendix/source-index.html">源码索引</a>。</p>',15)])])}const m=d(a,[["render",n]]);export{f as __pageData,m as default};
